import java.util.regex.Pattern;

/**
 * Class Kendaraan
 * Merepresentasikan armada kendaraan dalam AutoRent System.
 * Menerapkan prinsip Encapsulation dengan seluruh attribute private,
 * validasi data pada setter/constructor, dan pembatasan akses langsung.
 *
 * @author Ahmad Yasar Maulana Dais (NRP: 3125522018)
 * @version 3.0 (Modul 3 - Encapsulation & Validation)
 */
public class Kendaraan {
    // 1. Enkapsulasi: Seluruh attribute dideklarasikan dengan access modifier 'private'
    private String platNomor;
    private String merk;
    private String jenis;
    private double tarifPerHari;
    private boolean isTersedia;

    // Pola regex plat nomor Indonesia (contoh: "L 1234 AB", "B 9999 XYZ", "M 123 CD")
    private static final String REGEX_PLAT_NOMOR = "^[A-Z]{1,2}\\s[0-9]{1,4}\\s[A-Z]{1,3}$";
    private static final double MIN_TARIF_PER_HARI = 50000.0;

    // 2. Parameterized Constructor yang menerapkan Defensive Programming (memanggil validasi setter)
    public Kendaraan(String platNomor, String merk, String jenis, double tarifPerHari, boolean isTersedia) {
        // Menggunakan setter agar seluruh nilai awal wajib lolos aturan validasi data
        if (!setPlatNomor(platNomor)) {
            this.platNomor = "N/A (Invalid Plat)";
        }
        if (!setMerk(merk)) {
            this.merk = "Unit Standar (Default)";
        }
        if (!setJenis(jenis)) {
            this.jenis = "MPV (Default)";
        }
        if (!setTarifPerHari(tarifPerHari)) {
            this.tarifPerHari = MIN_TARIF_PER_HARI;
        }
        this.isTersedia = isTersedia;
    }

    // 3. Getter Methods (Controlled Read Access)
    public String getPlatNomor() {
        return platNomor;
    }

    public String getMerk() {
        return merk;
    }

    public String getJenis() {
        return jenis;
    }

    public double getTarifPerHari() {
        return tarifPerHari;
    }

    public boolean isUnitTersedia() {
        return isTersedia;
    }

    // 4. Setter Methods dengan Validasi Data Bisnis (Controlled Mutator Access)

    /**
     * Validasi 1: Format Plat Nomor Polisi
     * Plat nomor harus sesuai pola standar kepolisian (1-2 huruf kode wilayah, 1-4 digit angka, 1-3 huruf seri).
     */
    public boolean setPlatNomor(String platNomor) {
        if (platNomor != null && Pattern.matches(REGEX_PLAT_NOMOR, platNomor.trim().toUpperCase())) {
            this.platNomor = platNomor.trim().toUpperCase();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Plat nomor '" + platNomor + "' TIDAK VALID! Format baku harus sesuai: [Kode Wilayah] [Nomor] [Seri], contoh: 'L 1234 AB'");
            return false;
        }
    }

    /**
     * Validasi 2: Merk / Tipe Kendaraan
     * Merk tidak boleh null, tidak boleh kosong/hanya spasi, dan minimal 3 karakter.
     */
    public boolean setMerk(String merk) {
        if (merk != null && merk.trim().length() >= 3) {
            this.merk = merk.trim();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Merk kendaraan '" + merk + "' TIDAK VALID! Nama merk tidak boleh kosong dan minimal 3 karakter.");
            return false;
        }
    }

    /**
     * Validasi 3: Jenis / Kategori Armada
     * Kategori kendaraan tidak boleh null atau kosong.
     */
    public boolean setJenis(String jenis) {
        if (jenis != null && !jenis.trim().isEmpty()) {
            this.jenis = jenis.trim();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Jenis armada '" + jenis + "' TIDAK VALID! Kategori jenis kendaraan tidak boleh kosong.");
            return false;
        }
    }

    /**
     * Validasi 4: Tarif Sewa Per Hari
     * Tarif harian harus positif (> 0) dan memenuhi batas minimum operasional (>= Rp 50.000).
     */
    public boolean setTarifPerHari(double tarifPerHari) {
        if (tarifPerHari >= MIN_TARIF_PER_HARI) {
            this.tarifPerHari = tarifPerHari;
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Tarif per hari Rp " + String.format("%,.2f", tarifPerHari) + " TIDAK VALID! Tarif harus lebih besar dari 0 dan minimal Rp " + String.format("%,.2f", MIN_TARIF_PER_HARI));
            return false;
        }
    }

    public void setStatusKetersediaan(boolean isTersedia) {
        this.isTersedia = isTersedia;
        if (isTersedia) {
            System.out.println("  >> [Kendaraan " + this.platNomor + "] Status armada berhasil diubah: TERSEDIA (Ready)");
        } else {
            System.out.println("  >> [Kendaraan " + this.platNomor + "] Status armada berhasil diubah: SEDANG DISEWA (Booked)");
        }
    }

    // 5. Method Operasional & Komputasi State
    public void tampilkanInformasi() {
        System.out.println("  -------------------------------------------------------------");
        System.out.println("  [Plat Nomor]     : " + platNomor);
        System.out.println("  [Merk / Tipe]    : " + merk);
        System.out.println("  [Jenis Armada]   : " + jenis);
        System.out.println("  [Tarif Sewa/Hari]: Rp " + String.format("%,.2f", tarifPerHari));
        System.out.println("  [Status Unit]    : " + (isTersedia ? "TERSEDIA (Ready)" : "SEDANG DISEWA (Booked)"));
        System.out.println("  -------------------------------------------------------------");
    }

    public void updateTarif(double tarifBaru) {
        System.out.println("  >> Mengajukan pembaruan tarif armada " + platNomor + " menjadi Rp " + String.format("%,.2f", tarifBaru) + "...");
        if (setTarifPerHari(tarifBaru)) {
            System.out.println("  >> [SUKSES] Tarif armada " + platNomor + " berhasil diperbarui menjadi Rp " + String.format("%,.2f", this.tarifPerHari));
        } else {
            System.out.println("  >> [GAGAL] Pembaruan tarif ditolak. Nilai tarif armada tetap Rp " + String.format("%,.2f", this.tarifPerHari));
        }
    }

    public double hitungEstimasiSewa(int durasiHari) {
        if (durasiHari > 0) {
            return this.tarifPerHari * durasiHari;
        } else {
            System.out.println("  [VALIDATION ERROR] Durasi sewa (" + durasiHari + " hari) tidak valid untuk kalkulasi estimasi.");
            return 0.0;
        }
    }
}

import java.util.regex.Pattern;

/**
 * Class Pelanggan
 * Merepresentasikan data penyewa/pelanggan dalam AutoRent System.
 * Menerapkan prinsip Encapsulation dengan attribute private, identifier read-only,
 * validasi NIK/KTP 16 digit, validasi format telepon, dan kontrol ketat kuota sewa.
 *
 * @author Ahmad Yasar Maulana Dais (NRP: 3125522018)
 * @version 3.0 (Modul 3 - Encapsulation & Validation)
 */
public class Pelanggan {
    // 1. Enkapsulasi: Seluruh attribute berstatus 'private'
    private String idPelanggan;
    private String namaLengkap;
    private String nomorKtp;
    private String nomorTelepon;
    private int totalSewaAktif;

    // Aturan bisnis: Batas kuota maksimal unit sewa per pelanggan
    private static final int BATAS_MAX_SEWA = 2;

    // Pola regex validasi identitas dan kontak
    private static final String REGEX_KTP = "^[0-9]{16}$";
    private static final String REGEX_TELEPON = "^08[0-9]{8,12}$"; // Dimulai '08' total 10-14 digit

    // 2. Parameterized Constructor dengan validasi data defensif
    public Pelanggan(String idPelanggan, String namaLengkap, String nomorKtp, String nomorTelepon, int totalSewaAktif) {
        // Validasi ID Pelanggan (Identifier)
        if (idPelanggan != null && !idPelanggan.trim().isEmpty()) {
            this.idPelanggan = idPelanggan.trim().toUpperCase();
        } else {
            this.idPelanggan = "CUST-DEFAULT";
        }

        // Validasi Nama Lengkap
        if (!setNamaLengkap(namaLengkap)) {
            this.namaLengkap = "Pelanggan Tanpa Nama";
        }

        // Validasi Nomor KTP (16 Digit)
        if (!setNomorKtp(nomorKtp)) {
            this.nomorKtp = "0000000000000000";
        }

        // Validasi Nomor Telepon
        if (!setNomorTelepon(nomorTelepon)) {
            this.nomorTelepon = "081200000000";
        }

        // Validasi Initial Sewa Aktif
        if (totalSewaAktif >= 0 && totalSewaAktif <= BATAS_MAX_SEWA) {
            this.totalSewaAktif = totalSewaAktif;
        } else {
            this.totalSewaAktif = 0;
        }
    }

    // 3. Getter Methods (Controlled Read Access)
    public String getIdPelanggan() {
        return idPelanggan;
    }

    public String getNamaLengkap() {
        return namaLengkap;
    }

    public String getNomorKtp() {
        return nomorKtp;
    }

    public String getNomorTelepon() {
        return nomorTelepon;
    }

    public int getTotalSewaAktif() {
        return totalSewaAktif;
    }

    public int getBatasMaxSewa() {
        return BATAS_MAX_SEWA;
    }

    public int getSisaKuotaSewa() {
        return BATAS_MAX_SEWA - totalSewaAktif;
    }

    public boolean bolehSewa() {
        return totalSewaAktif < BATAS_MAX_SEWA;
    }

    // 4. Setter Methods dengan Validasi Data Bisnis

    /**
     * Validasi: Nama Lengkap Pelanggan
     * Nama tidak boleh null, tidak boleh kosong/whitespace, minimal 3 karakter.
     */
    public boolean setNamaLengkap(String namaLengkap) {
        if (namaLengkap != null && namaLengkap.trim().length() >= 3) {
            this.namaLengkap = namaLengkap.trim();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Nama pelanggan '" + namaLengkap + "' TIDAK VALID! Nama tidak boleh kosong dan minimal 3 karakter.");
            return false;
        }
    }

    /**
     * Validasi: Nomor KTP / NIK
     * Harus tepat 16 digit angka numerik.
     */
    public boolean setNomorKtp(String nomorKtp) {
        if (nomorKtp != null && Pattern.matches(REGEX_KTP, nomorKtp.trim())) {
            this.nomorKtp = nomorKtp.trim();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Nomor KTP '" + nomorKtp + "' TIDAK VALID! NIK/KTP harus tepat 16 digit angka numerik.");
            return false;
        }
    }

    /**
     * Validasi: Nomor Telepon
     * Harus berformat nomor seluler Indonesia diawali '08' dengan total panjang 10–14 digit.
     */
    public boolean setNomorTelepon(String nomorTelepon) {
        if (nomorTelepon != null && Pattern.matches(REGEX_TELEPON, nomorTelepon.trim())) {
            this.nomorTelepon = nomorTelepon.trim();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Nomor telepon '" + nomorTelepon + "' TIDAK VALID! Nomor harus diawali '08' dan terdiri dari 10-14 digit angka.");
            return false;
        }
    }

    // 5. Method Operasional & Mutasi State Terkendali (Controlled State Mutation)
    public void perbaruiKontak(String noTeleponBaru) {
        System.out.println("  >> Mengajukan pembaruan nomor kontak pelanggan " + idPelanggan + " menjadi '" + noTeleponBaru + "'...");
        if (setNomorTelepon(noTeleponBaru)) {
            System.out.println("  >> [SUKSES] Nomor kontak pelanggan " + idPelanggan + " (" + namaLengkap + ") berhasil diperbarui menjadi: " + this.nomorTelepon);
        } else {
            System.out.println("  >> [GAGAL] Pembaruan kontak ditolak. Nomor tetap: " + this.nomorTelepon);
        }
    }

    public boolean tambahSewaAktif(int jumlah) {
        if (jumlah <= 0) {
            System.out.println("  [VALIDATION ERROR] Jumlah penambahan unit sewa harus lebih dari 0.");
            return false;
        }
        if ((this.totalSewaAktif + jumlah) <= BATAS_MAX_SEWA) {
            this.totalSewaAktif += jumlah;
            System.out.println("  >> [Pelanggan " + idPelanggan + "] Transaksi sewa disetujui +" + jumlah + " unit. Total sewa aktif: " + this.totalSewaAktif + "/" + BATAS_MAX_SEWA);
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Penambahan sewa DITOLAK! Kuota sewa terlampaui. Maksimal: " + BATAS_MAX_SEWA + ", Sewa saat ini: " + this.totalSewaAktif);
            return false;
        }
    }

    public boolean kurangiSewaAktif(int jumlah) {
        if (jumlah <= 0) {
            System.out.println("  [VALIDATION ERROR] Jumlah pengurangan unit sewa harus lebih dari 0.");
            return false;
        }
        if ((this.totalSewaAktif - jumlah) >= 0) {
            this.totalSewaAktif -= jumlah;
            System.out.println("  >> [Pelanggan " + idPelanggan + "] Pengembalian tercatat -" + jumlah + " unit. Sisa sewa aktif: " + this.totalSewaAktif + "/" + BATAS_MAX_SEWA);
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Pengurangan sewa tidak valid! Jumlah sewa aktif tidak boleh kurang dari 0.");
            return false;
        }
    }

    public void tampilkanDataPelanggan() {
        System.out.println("  -------------------------------------------------------------");
        System.out.println("  [ID Pelanggan]      : " + idPelanggan);
        System.out.println("  [Nama Lengkap]      : " + namaLengkap);
        System.out.println("  [Nomor KTP / NIK]   : " + nomorKtp);
        System.out.println("  [Nomor Telepon]     : " + nomorTelepon);
        System.out.println("  [Unit Sedang Disewa]: " + totalSewaAktif + " unit");
        System.out.println("  [Sisa Kuota Sewa]   : " + getSisaKuotaSewa() + " unit (Max: " + BATAS_MAX_SEWA + ")");
        System.out.println("  [Status Hak Sewa]   : " + (bolehSewa() ? "DIIZINKAN SEWA" : "KUOTA PENUH"));
        System.out.println("  -------------------------------------------------------------");
    }
}

/**
 * Class TransaksiSewa
 * Mengelola transaksi pemesanan dan pengembalian sewa kendaraan.
 * Menghubungkan objek Kendaraan dan Pelanggan (Association Relationship).
 * Menerapkan prinsip Encapsulation dengan attribute private, validasi durasi sewa,
 * validasi ketersediaan unit armada, validasi kuota pelanggan, dan kalkulasi biaya terlindungi.
 *
 * @author Ahmad Yasar Maulana Dais (NRP: 3125522018)
 * @version 3.0 (Modul 3 - Encapsulation & Validation)
 */
public class TransaksiSewa {
    // 1. Enkapsulasi: Seluruh attribute dideklarasikan 'private'
    private String kodeTransaksi;
    private Kendaraan kendaraan;
    private Pelanggan pelanggan;
    private String tanggalSewa;
    private int durasiHari;
    private double totalBiaya;
    private String statusSewa;

    // Konstanta tarif denda per hari keterlambatan
    private static final double TARIF_DENDA_PER_HARI = 50000.0;

    // 2. Parameterized Constructor dengan Validasi Pra-Syarat Transaksi (Defensive Constructor)
    public TransaksiSewa(String kodeTransaksi, Kendaraan kendaraan, Pelanggan pelanggan, String tanggalSewa, int durasiHari) {
        // Validasi Kode Transaksi
        if (kodeTransaksi != null && !kodeTransaksi.trim().isEmpty()) {
            this.kodeTransaksi = kodeTransaksi.trim().toUpperCase();
        } else {
            this.kodeTransaksi = "TRX-UNKNOWN";
        }

        this.tanggalSewa = (tanggalSewa != null && !tanggalSewa.trim().isEmpty()) ? tanggalSewa.trim() : "01-01-2026";

        // Validasi Relasi Objek & Pra-Syarat Bisnis
        if (kendaraan == null) {
            System.out.println("  [TRANSACTION ERROR] Objek Kendaraan tidak boleh NULL!");
            this.statusSewa = "Dibatalkan (Kendaraan Null)";
            this.durasiHari = 0;
            this.totalBiaya = 0.0;
            return;
        }

        if (pelanggan == null) {
            System.out.println("  [TRANSACTION ERROR] Objek Pelanggan tidak boleh NULL!");
            this.statusSewa = "Dibatalkan (Pelanggan Null)";
            this.durasiHari = 0;
            this.totalBiaya = 0.0;
            return;
        }

        // Validasi Ketersediaan Unit Armada
        if (!kendaraan.isUnitTersedia()) {
            System.out.println("  [TRANSACTION ERROR] Unit kendaraan '" + kendaraan.getPlatNomor() + " (" + kendaraan.getMerk() + ")' SEDANG DISEWA / Tidak Tersedia!");
            this.kendaraan = kendaraan;
            this.pelanggan = pelanggan;
            this.statusSewa = "Ditolak (Armada Tidak Tersedia)";
            this.durasiHari = 0;
            this.totalBiaya = 0.0;
            return;
        }

        // Validasi Hak/Kuota Sewa Pelanggan
        if (!pelanggan.bolehSewa()) {
            System.out.println("  [TRANSACTION ERROR] Pelanggan '" + pelanggan.getNamaLengkap() + "' telah mencapai batas kuota maksimal sewa!");
            this.kendaraan = kendaraan;
            this.pelanggan = pelanggan;
            this.statusSewa = "Ditolak (Kuota Pelanggan Penuh)";
            this.durasiHari = 0;
            this.totalBiaya = 0.0;
            return;
        }

        // Validasi Durasi Sewa
        if (durasiHari <= 0) {
            System.out.println("  [VALIDATION ERROR] Durasi sewa (" + durasiHari + " hari) TIDAK VALID! Minimal durasi adalah 1 hari.");
            this.durasiHari = 1; // Fallback nilai minimum yang aman
        } else {
            this.durasiHari = durasiHari;
        }

        // Jika seluruh validasi lolos, inisialisasi state transaksi secara konsisten
        this.kendaraan = kendaraan;
        this.pelanggan = pelanggan;
        this.statusSewa = "Sedang Disewa";
        this.totalBiaya = this.kendaraan.hitungEstimasiSewa(this.durasiHari);

        // Mutasi state objek terkait secara otomatis (Encapsulated workflow)
        this.kendaraan.setStatusKetersediaan(false);
        this.pelanggan.tambahSewaAktif(1);
        System.out.println("  >> [SUKSES] Transaksi " + this.kodeTransaksi + " berhasil dibuat. Unit " + kendaraan.getPlatNomor() + " dipinjam oleh " + pelanggan.getNamaLengkap());
    }

    // 3. Getter Methods (Controlled Read Access)
    public String getKodeTransaksi() {
        return kodeTransaksi;
    }

    public Kendaraan getKendaraan() {
        return kendaraan;
    }

    public Pelanggan getPelanggan() {
        return pelanggan;
    }

    public String getTanggalSewa() {
        return tanggalSewa;
    }

    public int getDurasiHari() {
        return durasiHari;
    }

    public double getTotalBiaya() {
        return totalBiaya;
    }

    public String getStatusSewa() {
        return statusSewa;
    }

    public double getTarifDendaPerHari() {
        return TARIF_DENDA_PER_HARI;
    }

    // 4. Setter Methods dengan Validasi Terkontrol
    public boolean setTanggalSewa(String tanggalSewa) {
        if (tanggalSewa != null && !tanggalSewa.trim().isEmpty()) {
            this.tanggalSewa = tanggalSewa.trim();
            return true;
        } else {
            System.out.println("  [VALIDATION ERROR] Tanggal sewa tidak boleh kosong.");
            return false;
        }
    }

    // 5. Method Operasional & Mutasi Status Transaksi
    public boolean perpanjangDurasi(int tambahanHari) {
        System.out.println("  >> Mengajukan perpanjangan durasi transaksi " + kodeTransaksi + " sebesar +" + tambahanHari + " hari...");
        if (!"Sedang Disewa".equalsIgnoreCase(this.statusSewa)) {
            System.out.println("  [VALIDATION ERROR] Perpanjangan ditolak! Transaksi sudah berstatus '" + this.statusSewa + "'.");
            return false;
        }
        if (tambahanHari <= 0) {
            System.out.println("  [VALIDATION ERROR] Tambahan hari (" + tambahanHari + " hari) TIDAK VALID! Nilai harus lebih dari 0.");
            return false;
        }

        this.durasiHari += tambahanHari;
        double biayaTambahan = this.kendaraan.hitungEstimasiSewa(tambahanHari);
        this.totalBiaya += biayaTambahan;
        System.out.println("  >> [SUKSES] Perpanjangan sewa disetujui. Total durasi baru: " + this.durasiHari + " hari | Total biaya akhir: Rp " + String.format("%,.2f", this.totalBiaya));
        return true;
    }

    public boolean prosesPengembalian(int hariKeterlambatan) {
        System.out.println("  >> Memproses pengembalian kendaraan untuk Transaksi " + kodeTransaksi + "...");
        if (!"Sedang Disewa".equalsIgnoreCase(this.statusSewa)) {
            System.out.println("  [VALIDATION ERROR] Pengembalian ditolak! Transaksi tidak dalam status aktif ('" + this.statusSewa + "').");
            return false;
        }

        if (hariKeterlambatan < 0) {
            System.out.println("  [VALIDATION ERROR] Hari keterlambatan (" + hariKeterlambatan + ") tidak valid! Menggunakan 0 hari keterlambatan.");
            hariKeterlambatan = 0;
        }

        this.statusSewa = "Selesai";
        this.kendaraan.setStatusKetersediaan(true);
        this.pelanggan.kurangiSewaAktif(1);

        double denda = hitungDenda(hariKeterlambatan);
        double totalAkhir = this.totalBiaya + denda;

        System.out.println("  >> [SUKSES] Unit kendaraan " + kendaraan.getPlatNomor() + " (" + kendaraan.getMerk() + ") berhasil dikembalikan.");
        if (hariKeterlambatan > 0) {
            System.out.println("     [Status Keterlambatan] : Terlambat " + hariKeterlambatan + " hari");
            System.out.println("     [Denda Dikenakan]      : Rp " + String.format("%,.2f", denda) + " (Rp 50.000 / hari)");
            System.out.println("     [Total Tagihan Akhir]  : Rp " + String.format("%,.2f", totalAkhir));
        } else {
            System.out.println("     [Status Keterlambatan] : Tepat Waktu (Bebas Denda)");
            System.out.println("     [Total Tagihan Akhir]  : Rp " + String.format("%,.2f", totalAkhir));
        }
        return true;
    }

    public double hitungDenda(int hariKeterlambatan) {
        return (hariKeterlambatan > 0) ? hariKeterlambatan * TARIF_DENDA_PER_HARI : 0.0;
    }

    public void cetakStrukSewa() {
        System.out.println("  =============================================================");
        System.out.println("            STRUK BUKTI TRANSAKSI SEWA - AUTORENT SYSTEM       ");
        System.out.println("  =============================================================");
        System.out.println("  [Kode Transaksi] : " + kodeTransaksi);
        System.out.println("  [Tanggal Sewa]   : " + tanggalSewa);
        System.out.println("  [Durasi Sewa]    : " + durasiHari + " hari");
        System.out.println("  [Status Transaksi]: " + statusSewa);
        System.out.println("  -------------------------------------------------------------");
        if (pelanggan != null) {
            System.out.println("  Penyewa        : " + pelanggan.getNamaLengkap() + " (ID: " + pelanggan.getIdPelanggan() + ")");
            System.out.println("  Nomor Kontak   : " + pelanggan.getNomorTelepon());
            System.out.println("  Nomor KTP      : " + pelanggan.getNomorKtp());
        }
        if (kendaraan != null) {
            System.out.println("  Armada         : " + kendaraan.getMerk() + " [" + kendaraan.getJenis() + "]");
